import zipfile
import re
from xml.etree import ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
REL_NS = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
PKG_REL_NS = 'http://schemas.openxmlformats.org/package/2006/relationships'

path = 'budget.xlsx'
z = zipfile.ZipFile(path)
print("Files in archive:")
for n in z.namelist():
    print("  ", n)

# workbook -> sheets
wb_xml = ET.fromstring(z.read('xl/workbook.xml'))
sheets = []
for sh in wb_xml.find('m:sheets', NS):
    sheets.append((sh.get('name'), sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))
print("\nSheets (name, rId):", sheets)

# map rId -> target
rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
relmap = {}
for r in rels:
    relmap[r.get('Id')] = r.get('Target')

shared_strings = []
if 'xl/sharedStrings.xml' in z.namelist():
    ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in ss.findall('m:si', NS):
        text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
        shared_strings.append(text)
print("\nShared strings:", shared_strings)

for name, rid in sheets:
    target = relmap[rid]
    if not target.startswith('xl/'):
        target = 'xl/' + target.lstrip('/')
    ws_xml = ET.fromstring(z.read(target))
    print(f"\n=== Sheet: {name} ===")
    for row in ws_xml.find('m:sheetData', NS):
        cells = []
        for c in row:
            ref = c.get('r')
            t = c.get('t')
            v = c.find('m:v', NS)
            val = v.text if v is not None else None
            if t == 's' and val is not None:
                val = shared_strings[int(val)]
            elif t == 'b':
                val = val == '1'
            elif t == 'inlineStr':
                is_el = c.find('m:is', NS)
                val = ''.join(x.text or '' for x in is_el.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')) if is_el is not None else None
            if val is not None:
                cells.append((ref, val))
        if cells:
            print(cells)

