import zipfile
from xml.etree import ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
REL = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'

path = 'budget.xlsx'
z = zipfile.ZipFile(path)

wb_xml = ET.fromstring(z.read('xl/workbook.xml'))
rid = next(sh.get(REL + 'id') for sh in wb_xml.find('m:sheets', NS) if sh.get('name') == 'Budget')
rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
target = next(r.get('Target') for r in rels if r.get('Id') == rid).lstrip('/')
ws_xml = ET.fromstring(z.read(target if target.startswith('xl/') else 'xl/' + target))

rows = {}
for row in ws_xml.find('m:sheetData', NS):
    for c in row:
        ref = c.get('r')
        v = c.find('m:v', NS)
        val = v.text if v is not None else None
        if val is not None:
            try:
                rows[ref] = float(val)
            except (TypeError, ValueError):
                rows[ref] = val

expense_rows = [f'{col}{r}' for r in range(11, 23) for col in ('A', 'C')]
expenses = [(rows.get(f'A{r}'), rows.get(f'C{r}')) for r in range(11, 23)]

by_cat = {}
total = 0.0
for cat, amount in expenses:
    if cat is None or amount is None:
        continue
    by_cat[cat] = by_cat.get(cat, 0.0) + amount
    total += amount

for cat, amt in by_cat.items():
    print(f"{cat}: {amt:.2f}")
print(f"TOTAL EXPENSES: {total:.2f}")

